"""Writes patches.json: the factory synth sounds.
Run:  python -m mpkloop.factory.build_patches

Fields: osc (saw2 super saw1 square pulse tri sine bass fm organ), amp ADSR,
fenv ADSR + fenv_amt (octaves), cutoff, reso, gain, and the extras detune (cents),
sub, pw, intervals (semitones), noise, vib (semitones), ratio/index (fm)."""
import json
from pathlib import Path


def p(cat, name, osc, amp, fenv=(0.01, 0.3, 1.0, 0.3), fenv_amt=0.0, cutoff=16000, reso=0.0, gain=0.3, **kw):
    return dict(cat=cat, name=name, osc=osc, amp=list(amp), fenv=list(fenv), fenv_amt=fenv_amt,
                cutoff=cutoff, reso=reso, gain=gain, **kw)


